const ASSETS = {"/":{"type":"text/html; charset=utf-8","data":""},"/app.js":{"type":"text/javascript; charset=utf-8","data":""},"/content.js":{"type":"text/javascript; charset=utf-8","data":""},"/styles.css":{"type":"text/css; charset=utf-8","data":""},"/assets/costaatt-logo.webp":{"type":"image/webp","data":""},"/assets/costaatt-workshop-qr.svg":{"type":"image/svg+xml","data":""}};
const JSON_HEADERS = {'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'};
function json(status,payload){return new Response(JSON.stringify(payload),{status,headers:JSON_HEADERS});}
function validIso(value){const date=new Date(value);return Number.isFinite(date.getTime())?date.toISOString():new Date().toISOString();}
function ownerAuthorization(request,env){if(!env.REPORTING_OWNER_ID)return json(503,{error:'Owner access is not configured.'});const id=request.headers.get('oai-authenticated-user-id');if(!id)return json(401,{error:'Sign in with the workshop owner account.'});if(id!==env.REPORTING_OWNER_ID)return json(403,{error:'Owner access only.'});return null;}
function cleanPayload(payload){const id=String(payload?.id||'').trim().slice(0,120);const name=String(payload?.name||'').trim().slice(0,120);const role=String(payload?.role||'').trim().slice(0,160);const org=String(payload?.org||'').trim().slice(0,160);const completed=[...new Set(Array.isArray(payload?.completed)?payload.completed.filter(Number.isInteger).filter(x=>x>=0&&x<8):[])].sort((a,b)=>a-b);const challenges=Math.max(0,Math.min(99,Number.parseInt(payload?.challenges,10)||0));const gameAnswers=Math.max(0,Math.min(99,Number.parseInt(payload?.gameAnswers,10)||0));if(!id||!name||!role||payload?.consent!==true)throw new Error('Participant consent and required profile fields are required.');return {id,name,role,org,completed,challenges,gameAnswers,lastSeen:validIso(payload?.lastSeen),joinedAt:validIso(payload?.joinedAt||payload?.lastSeen)};}
function cleanProjection(payload){const p=payload?.projection||{},session=Number(p.session),activity=Number(p.activity),mode=String(p.mode||'');if(!Number.isInteger(session)||session<0||session>7||!Number.isInteger(activity)||activity<0||activity>9||!['challenge','timer','discussion','reveal'].includes(mode))throw new Error('Invalid projection state.');let timer=null;if(payload?.timer&&typeof payload.timer==='object'){const rawEnd=Number(payload.timer.endAt),endAt=Number.isFinite(rawEnd)&&rawEnd>0?rawEnd:null,remaining=Math.max(0,Math.min(7200,Number.parseInt(payload.timer.remaining,10)||0));if(endAt&&endAt>Date.now()+7200000)throw new Error('Timer exceeds the session limit.');timer={endAt,remaining};}return {projection:{session,activity,mode},timer};}
async function api(request,env,url){if(!env.DB)return json(503,{error:'Shared storage is not configured.'});if(request.method==='GET'&&url.pathname==='/api/participants'){const denied=ownerAuthorization(request,env);if(denied)return denied;const result=await env.DB.prepare('SELECT name,role,organization AS org,completed_json,challenge_count AS challengeCount,game_answer_count AS gameAnswerCount FROM participants ORDER BY last_seen DESC').all();const participants=(result.results||[]).map(row=>{let completed=[];try{completed=JSON.parse(row.completed_json||'[]');}catch{}return {name:row.name,role:row.role,org:row.org,completedCount:Array.isArray(completed)?completed.length:0,challengeCount:row.challengeCount||0,gameAnswerCount:row.gameAnswerCount||0};});return json(200,{participants});}if(request.method==='POST'&&url.pathname==='/api/participants'){try{const incoming=cleanPayload(await request.json());const previous=await env.DB.prepare('SELECT joined_at,last_seen FROM participants WHERE participant_id = ?').bind(incoming.id).first();await env.DB.prepare('INSERT INTO participants (participant_id,name,role,organization,consent,completed_json,challenge_count,game_answer_count,joined_at,last_seen) VALUES (?,?,?,?,?,?,?,?,?,?) ON CONFLICT(participant_id) DO UPDATE SET name=excluded.name,role=excluded.role,organization=excluded.organization,consent=excluded.consent,completed_json=excluded.completed_json,challenge_count=excluded.challenge_count,game_answer_count=excluded.game_answer_count,last_seen=participants.last_seen').bind(incoming.id,incoming.name,incoming.role,incoming.org,1,JSON.stringify(incoming.completed),incoming.challenges,incoming.gameAnswers,previous?.joined_at||incoming.joinedAt,previous?.last_seen||incoming.joinedAt).run();return json(200,{ok:true});}catch(error){return json(400,{error:error instanceof Error?error.message:'Invalid participant data'});}}if(request.method==='DELETE'&&url.pathname==='/api/participants'){const denied=ownerAuthorization(request,env);if(denied)return denied;await env.DB.prepare('DELETE FROM participants').run();return new Response(null,{status:204,headers:JSON_HEADERS});}const participantPrefix='/api/participants/',participantDeleteId=url.pathname.startsWith(participantPrefix)?decodeURIComponent(url.pathname.slice(participantPrefix.length)):'';if(request.method==='DELETE'&&/^[a-zA-Z0-9-]{1,120}$/.test(participantDeleteId)){await env.DB.prepare('DELETE FROM participants WHERE participant_id = ?').bind(participantDeleteId).run();return new Response(null,{status:204,headers:JSON_HEADERS});}if(request.method==='POST'&&url.pathname==='/api/projection/rooms'){const denied=ownerAuthorization(request,env);if(denied)return denied;let projection;try{projection=cleanProjection(await request.json());}catch(error){return json(400,{error:error instanceof Error?error.message:'Invalid projection state'});}const now=new Date().toISOString(),expiresAt=new Date(Date.now()+12*60*60*1000).toISOString(),roomId=crypto.randomUUID();await env.DB.prepare('DELETE FROM projection_rooms WHERE expires_at <= ?').bind(now).run();await env.DB.prepare('INSERT INTO projection_rooms (room_id,state_json,created_at,updated_at,expires_at) VALUES (?,?,?,?,?)').bind(roomId,JSON.stringify(projection),now,now,expiresAt).run();return json(201,{roomId,expiresAt});}const roomSegments=url.pathname.split('/'),roomId=roomSegments[4]||'',roomMatch=url.pathname.startsWith('/api/projection/rooms/')&&/^[0-9a-f-]{36}$/i.test(roomId);if(roomMatch){if(request.method==='GET'){const now=new Date().toISOString(),row=await env.DB.prepare('SELECT state_json,updated_at,expires_at FROM projection_rooms WHERE room_id = ? AND expires_at > ?').bind(roomId,now).first();if(!row)return json(404,{error:'Projection room not found.'});let state;try{state=JSON.parse(row.state_json);}catch{return json(500,{error:'Projection state is unavailable.'});}return json(200,{state,updatedAt:row.updated_at,expiresAt:row.expires_at});}if(request.method==='PUT'||request.method==='DELETE'){const denied=ownerAuthorization(request,env);if(denied)return denied;const now=new Date().toISOString();if(request.method==='DELETE'){const result=await env.DB.prepare('DELETE FROM projection_rooms WHERE room_id = ? AND expires_at > ?').bind(roomId,now).run();if(result.meta?.changes===0)return json(404,{error:'Projection room not found.'});return new Response(null,{status:204,headers:JSON_HEADERS});}let projection;try{projection=cleanProjection(await request.json());}catch(error){return json(400,{error:error instanceof Error?error.message:'Invalid projection state'});}const result=await env.DB.prepare('UPDATE projection_rooms SET state_json = ?, updated_at = ? WHERE room_id = ? AND expires_at > ?').bind(JSON.stringify(projection),now,roomId,now).run();if(result.meta?.changes===0)return json(404,{error:'Projection room not found.'});return json(200,{ok:true});}}return json(404,{error:'API route not found'});}
function assetResponse(url){const asset=ASSETS[url.pathname]||ASSETS['/'];if(!asset||url.pathname!=='/'&&!ASSETS[url.pathname])return new Response('Not found',{status:404,headers:{'content-type':'text/plain; charset=utf-8'}});const bytes=Uint8Array.from(atob(asset.data),char=>char.charCodeAt(0));return new Response(bytes,{headers:{'content-type':asset.type,'cache-control':'no-store','x-content-type-options':'nosniff','referrer-policy':'strict-origin-when-cross-origin'}});}
export default {async fetch(request,env,ctx){void ctx;const url=new URL(request.url);if(url.pathname.startsWith('/api/')){try{return await api(request,env,url);}catch(error){return json(500,{error:error instanceof Error?error.message:'Unexpected reporting error'});}}return assetResponse(url);}};
